    ('vw_assignment_status', "CREATE VIEW `vw_assignment_status` AS select `A`.`training_id` AS `training_id`,`A`.`uid` AS `uid`,`P`.`name` AS `trainee_name`,`P`.`is_active` AS `is_active`,`P`.`store_id` AS `store_id`,`P`.`store_name` AS `store_name`,`P`.`district_name` AS `district_name`,`P`.`market_name` AS `market_name`,`P`.`region_name` AS `region_name`,`A`.`assigned_at` AS `assigned_at`,`A`.`due_at` AS `due_at`,coalesce(`G`.`status`,'not_started') AS `progress_status`,`G`.`sessions_count` AS `sessions_count`,`G`.`passed_at` AS `passed_at`,((`G`.`passed_at` is null) and (`A`.`due_at` is not null) and (`A`.`due_at` < utc_timestamp(3))) AS `is_overdue` from ((`training_assignments` `A` left join `vw_trainees` `P` on((`P`.`uid` = `A`.`uid`))) left join `training_progress` `G` on(((`G`.`uid` = `A`.`uid`) and (`G`.`training_id` = `A`.`training_id`)))) where (`A`.`status` <> 'cancelled')"),
    ('vw_question_stats', 'CREATE VIEW `vw_question_stats` AS select `Q`.`training_id` AS `training_id`,`Q`.`version_id` AS `version_id`,`Q`.`question_number` AS `question_number`,`Q`.`section_code` AS `section_code`,count(0) AS `answers`,sum((`Q`.`round` = 1)) AS `first_try_answers`,round(((100 * sum(((`Q`.`round` = 1) and (0 <> `Q`.`is_correct`)))) / nullif(sum((`Q`.`round` = 1)),0)),1) AS `first_try_correct_pct`,round(((100 * sum(`Q`.`is_correct`)) / count(0)),1) AS `overall_correct_pct` from `quiz_answers` `Q` group by `Q`.`training_id`,`Q`.`version_id`,`Q`.`question_number`,`Q`.`section_code`'),
    ('vw_session_report', 'CREATE VIEW `vw_session_report` AS select `X`.`session_id` AS `session_id`,`X`.`training_id` AS `training_id`,`T`.`title` AS `training_title`,`X`.`version_id` AS `version_id`,`X`.`uid` AS `uid`,`P`.`name` AS `trainee_name`,`X`.`job_title_at_session` AS `job_title_at_session`,`X`.`store_id_at_session` AS `store_id`,`S`.`store_name` AS `store_name`,`S`.`district_name` AS `district_name`,`S`.`market_name` AS `market_name`,`S`.`region_name` AS `region_name`,`X`.`location_type_at_session` AS `location_type_at_session`,`X`.`started_at` AS `started_at`,`X`.`ended_at` AS `ended_at`,`X`.`duration_sec` AS `duration_sec`,`X`.`start_point` AS `start_point`,`X`.`outcome` AS `outcome`,`X`.`end_reason` AS `end_reason`,`X`.`client` AS `client`,`X`.`profile_id` AS `profile_id`,`X`.`llm_model` AS `llm_model`,`X`.`voice_id` AS `voice_id`,`X`.`recording_s3_key` AS `recording_s3_key`,`U`.`est_total_cost` AS `est_total_cost`,`F`.`rating` AS `rating`,`F`.`comment` AS `feedback_comment` from (((((`training_sessions` `X` join `trainings` `T` on((`T`.`training_id` = `X`.`training_id`))) left join `vw_trainees` `P` on((`P`.`uid` = `X`.`uid`))) left join `vw_training_stores` `S` on((`S`.`store_id` = `X`.`store_id_at_session`))) left join `training_feedback` `F` on((`F`.`session_id` = `X`.`session_id`))) left join `session_usage` `U` on((`U`.`session_id` = `X`.`session_id`)))'),
