def _adapt(sql: str, is_mariadb: bool) -> str:
    return sql.replace("utf8mb4_0900_ai_ci", "utf8mb4_unicode_ci") if is_mariadb else sql


def upgrade() -> None:
    bind = op.get_bind()
    existing = set(sa.inspect(bind).get_table_names())
    if "training_sessions" in existing or "trainings" in existing:
        raise RuntimeError(
            "This database already has the agent's tables. The baseline must be STAMPED here, not upgraded: "
            "alembic stamp 0001_baseline"
        )
    is_mariadb = "mariadb" in str(bind.dialect.server_version_info).lower() or getattr(bind.dialect, "is_mariadb", False)
    for _, ddl in TABLES:
        op.execute(_adapt(ddl, is_mariadb))
    for _, ddl in VIEWS:
        op.execute(_adapt(ddl, is_mariadb))


def downgrade() -> None:
    raise RuntimeError("The baseline is never downgraded (SPEC §0.4).")
